// Picks the active breakpoint, mobile-first: largest min-width that fits
function activeBreakpoint(width, breakpoints) {
  let active = breakpoints[0].name;
  for (const bp of breakpoints) {
    if (width >= bp.min) {
      active = bp.name;
    }
  }
  return active;
}
const bps = [
  { name: "mobile", min: 0 },
  { name: "tablet", min: 768 },
  { name: "desktop", min: 1024 },
];
console.log(activeBreakpoint(900, bps));

