// Builds a grid-template-columns value for a responsive card grid
function gridColumns(itemCount, maxPerRow) {
  const columns = Math.min(itemCount, maxPerRow);
  return `repeat(${columns}, 1fr)`;
}
console.log(gridColumns(7, 3));

